def find_longest_palindrome_word(s):
    best = ''
    for word in s.split():
        lw = word.lower()
        if lw == lw[::-1]:
            if len(word) > len(best):
                best = word
    return best

def replace_nth_occurrence(s, ch, n, replacement):
    count = 0
    result = []
    for c in s:
        if c == ch:
            count += 1
            if count == n:
                result.append(replacement)
                continue
        result.append(c)
    if count < n:
        return s
    return ''.join(result)

from collections import Counter

def char_count_difference(a, b):
    ca, cb = Counter(a), Counter(b)
    chars = set(ca) | set(cb)
    return sum(abs(ca[c] - cb[c]) for c in chars)

def min_adjacent_swaps_to_sort(arr):
    n = len(arr)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                count += 1
    return count

def dedupe_extension(name):
    parts = name.split('.')
    if len(parts) >= 3 and parts[-1] != '' and parts[-1] == parts[-2]:
        return '.'.join(parts[:-1])
    return name

def int_to_roman(n):
    vals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
    ]
    result = []
    for value, symbol in vals:
        while n >= value:
            result.append(symbol)
            n -= value
    return ''.join(result)

