def local_to_utc(hh, mm, utc_offset_minutes):
    total_local = hh * 60 + mm
    total_utc = total_local - utc_offset_minutes
    day_delta = 0
    while total_utc < 0:
        total_utc += 1440
        day_delta -= 1
    while total_utc >= 1440:
        total_utc -= 1440
        day_delta += 1
    return (total_utc // 60, total_utc % 60, day_delta)

def top_k_names_multi_criteria(records, k):
    sorted_records = sorted(records, key=lambda r: (-r[1], r[2], r[0]))
    return [r[0] for r in sorted_records[:k]]

def stable_unique_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def is_valid_weighted_checksum_ascending_mod11(s):
    if len(s) < 2:
        return False
    body, check = s[:-1], s[-1]
    if not body or not body.isdigit():
        return False
    total = sum((i + 1) * int(d) for i, d in enumerate(body))
    remainder = total % 11
    if remainder == 10:
        return check == 'X'
    return check == str(remainder)

def rle_num_groups(lst):
    if not lst:
        return 0
    count = 1
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            count += 1
    return count

def countdown_string(start_hhmm, end_hhmm):
    def to_minutes(t):
        h, m = t.split(':')
        return int(h) * 60 + int(m)
    s = to_minutes(start_hhmm)
    e = to_minutes(end_hhmm)
    if e <= s:
        e += 24 * 60
    diff = e - s
    hours = diff // 60
    minutes = diff % 60
    return str(hours) + ':' + str(minutes).zfill(2)

def pad_to_multiple(s, multiple, ch):
    remainder = len(s) % multiple
    if remainder == 0:
        return s
    pad_len = multiple - remainder
    return s + ch * pad_len
